import { execSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import path from 'node:path';

const root = process.cwd();
const files = execSync("git ls-files", { encoding: 'utf8' }).split('\n').filter(f => f.endsWith('.mjs'));
const PACK = 'packs/claudinite-tasks/';
const IMPORT_RE = /^\s*(?:import|export)\s[^\n]*?from\s+['"]([^'"]+)['"]|^\s*import\s*\(\s*['"]([^'"]+)['"]|await import\(\s*['"]([^'"]+)['"]/gm;

const edges = [];
for (const f of files) {
  let src;
  try { src = readFileSync(path.join(root, f), 'utf8'); } catch { continue; }
  IMPORT_RE.lastIndex = 0;
  let m;
  while ((m = IMPORT_RE.exec(src))) {
    const spec = m[1] || m[2] || m[3];
    if (!spec || !spec.startsWith('.')) continue;
    const target = path.normalize(path.join(path.dirname(f), spec));
    if (target.startsWith(PACK)) edges.push({ from: f, to: target });
  }
}
const mode = process.argv[2];
if (mode === 'consumers') {
  const out = edges.filter(e => !e.from.startsWith(PACK));
  for (const e of out) console.log(`${e.from} -> ${e.to.slice(PACK.length)}`);
} else if (mode === 'fanin') {
  const c = {};
  for (const e of edges) c[e.to] = (c[e.to] || 0) + 1;
  Object.entries(c).sort((a,b)=>b[1]-a[1]).forEach(([k,v])=>console.log(v, k.slice(PACK.length)));
} else {
  for (const e of edges) if (e.from.startsWith(PACK)) console.log(`${e.from.slice(PACK.length)} -> ${e.to.slice(PACK.length)}`);
}
EOF
