    const at = `barrier rule #${i + 1}`;
    if (!spec || typeof spec !== 'object' || Array.isArray(spec)) {
      errors.push({ what: `${at} must be an object`, fix: 'use { "from": "...", "to": "..." } or { "between": ["a","b"] }' });
      return;
    }
