// The URL of the run doing the reporting, or null outside Actions.
export const runUrl = (env = process.env) => (env.GITHUB_RUN_ID
  ? `${env.GITHUB_SERVER_URL ?? 'https://github.com'}/${env.GITHUB_REPOSITORY}/actions/runs/${env.GITHUB_RUN_ID}`
  : null);

export const SCHEDULER_FAILURE_TITLE = 'Claudinite scheduler run failed';

// The scheduler workflow's `report-failure` job. It runs only when the scheduler
// run or its drain went red, so it files unconditionally.
async function main() {
  const { repo } = actionRepoContext();
  if (!repo) throw new Error('GITHUB_REPOSITORY is not set');
  const gh = makeGh();
  const { issue, created } = await reportWorkflowFailure(gh, repo, {
    title: SCHEDULER_FAILURE_TITLE,
    body: `The Claudinite scheduler run/drain run failed: ${runUrl()}`,
  });
  console.log(`- ${created ? 'filed' : 'commented on'} #${issue}`);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((e) => { console.error(e); process.exit(1); });
}
// COMPATIBILITY ENTRY POINT — "the tick" was renamed to the scheduler run (#877),
// and the mechanism now lives in `scheduler-run.mjs` beside this file. Nothing in
// the canon imports this path.
//
// WHY IT MUST EXIST. A member's `.github/workflows/claudinite-scheduler.yml` names
// the module it runs as a literal path, and that file is the ONE path a converge
// cannot push: it lands as a pull request the member has to merge, on its own
// cycle, while the mount beside it refreshes nightly. So every member spends a
// window running the new mount from an old workflow — and a workflow whose
// `node .claudinite/shared/packs/claudinite-tasks/queue/tick.mjs` finds nothing is a
// repo whose whole queue stops, silently, with no run left to fix it.
//
// WHEN IT GOES. When no member's `.github/workflows/claudinite-scheduler.yml`
// still names this path — read the members' workflow files, do not guess a date.

import { runSchedulerRun } from './scheduler-run.mjs';

console.log('- invoked as `tick.mjs`, which is the old name for the scheduler run —'
  + ' this repo\'s scheduler workflow is behind the mount and should be re-converged');
runSchedulerRun().catch((e) => { console.error(e); process.exit(1); });
// THE POST-SCHEDULER-RUN DRAIN (docs/PRINCIPLES.md). The
// scheduler run's own concurrency group serializes scheduler runs — its
// duplicate-standing-item self-heal depends on exactly that — and a drain running
// inside the group would make each tick queue behind the previous one's work,
// which the heartbeat, by making long work legal, turned from theoretical into
// likely. So the drain DISPATCHES the executor workflow rather than being one: it
// starts in its own group, on its own runner, and this step's success means "the
// drain was started", never "the drain finished".
//
// This is the guaranteed delivery. A `task:ready` label event may be lost; this
// fires on every tick that left something pickable, so a lost event is latency
// lost and never work lost.
//
// The workflow gates this step on the scheduler run's own `pickable` output — an
// executor dispatched into an empty queue costs a full billed invocation to find
// nothing. That gate weakens no delivery: what a lost label event would have
// delivered is exactly what the scheduler run's parting look already saw.

import { pathToFileURL } from 'node:url';
import { makeGh, actionRepoContext, EXECUTOR_WORKFLOW_FILE } from '../signals/gh.mjs';
import { dispatchWorkflow } from '../github.mjs';

async function main() {
  const { repo, defaultBranch } = actionRepoContext();
  if (!repo) throw new Error('GITHUB_REPOSITORY is not set');
  const { ok, status } = await dispatchWorkflow(makeGh(), repo, EXECUTOR_WORKFLOW_FILE, defaultBranch);
  // Judged by status, never by the body: a token without `actions: write` 403s
  // this POST with a plausible JSON body, and a run that logged `ok` for it would
  // leave the queue undrained with nothing saying so.
  if (!ok) throw new Error(`could not dispatch ${EXECUTOR_WORKFLOW_FILE} on ${defaultBranch}: ${status}`);
  console.log(`- dispatched the executor on ${defaultBranch} to drain whatever this scheduler run created`);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((e) => { console.error(e); process.exit(1); });
}

