// One-shot re-shelve driver: git-mv every module per moves.json, then re-resolve
// every relative import specifier in the repo against the old->new map.
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import path from 'node:path';

const ROOT = '/home/user/Claudinite';
const PACK = 'packs/claudinite-tasks/';
const SCRATCH = '/tmp/claude-0/-home-user-Claudinite/1082a465-9e8e-5504-86ab-af38b1cab767/scratchpad';
const raw = JSON.parse(readFileSync(path.join(SCRATCH, 'moves.json'), 'utf8'));

// Repo-relative old -> new. `github.mjs` folds INTO the moved signals/gh.mjs, so
// it maps to the same destination and its body is merged by hand afterwards.
const map = new Map();
for (const [from, to] of Object.entries(raw)) map.set(PACK + from, PACK + to);
map.set(PACK + 'github.mjs', PACK + 'src/world/github.mjs');

const doMove = process.argv.includes('--move');
const files = execFileSync('git', ['ls-files'], { cwd: ROOT, encoding: 'utf8' }).split('\n').filter(Boolean);

if (doMove) {
  for (const [from, to] of map) {
    if (from.endsWith(PACK + 'github.mjs')) continue; // merged by hand
    if (!existsSync(path.join(ROOT, from))) { console.error('MISSING', from); continue; }
    mkdirSync(path.join(ROOT, path.dirname(to)), { recursive: true });
    execFileSync('git', ['mv', from, to], { cwd: ROOT });
  }
  // signals/gh.mjs already landed at src/world/github.mjs; fold the writes in.
  const writes = readFileSync(path.join(ROOT, PACK + 'github.mjs'), 'utf8');
  writeFileSync(path.join(SCRATCH, 'github-writes.mjs'), writes);
  execFileSync('git', ['rm', '-q', PACK + 'github.mjs'], { cwd: ROOT });
  console.log('moved', map.size - 1, 'files');
  process.exit(0);
}

// --- import rewrite -------------------------------------------------------
// Anchored to real import/export syntax: a line-start `import`/`export … from`,
// or a dynamic `import(` — never a bare quoted string, which in this tree is
// routinely a path fixture rather than a module edge.
const SPEC_RE = /(^\s*(?:import|export)\b[\s\S]*?\bfrom\s*|(?:^|[^.\w])import\s*\(\s*)(['"])([^'"]+)\2/gm;

let changed = 0;
for (const nowPath of files) {
  if (!/\.mjs$/.test(nowPath)) continue;
  // Where this file USED to live decides how its relative specifiers resolved.
  const wasPath = [...map].find(([, to]) => to === nowPath)?.[0] ?? nowPath;
  const abs = path.join(ROOT, nowPath);
  if (!existsSync(abs)) continue;
  const src = readFileSync(abs, 'utf8');
  const out = src.replace(SPEC_RE, (m, head, q, spec) => {
    if (!spec.startsWith('.')) return m;
    const oldTarget = path.posix.normalize(path.posix.join(path.posix.dirname(wasPath), spec));
    const newTarget = map.get(oldTarget);
    if (!newTarget && !map.has(path.posix.dirname(nowPath))) {
      // The target did not move; the FILE may have, so re-derive either way.
      const rel = path.posix.relative(path.posix.dirname(nowPath), oldTarget);
      const next = rel.startsWith('.') ? rel : `./${rel}`;
      return next === spec ? m : `${head}${q}${next}${q}`;
    }
    const rel = path.posix.relative(path.posix.dirname(nowPath), newTarget ?? oldTarget);
    const next = rel.startsWith('.') ? rel : `./${rel}`;
    return next === spec ? m : `${head}${q}${next}${q}`;
  });
  if (out !== src) { writeFileSync(abs, out); changed += 1; }
}
console.log('rewrote imports in', changed, 'files');

