export { evaluatePrecondition } from '../src/execute/loop.mjs';
== shared-code/pull-requests.mjs
// The merged-PR field derivations, published for other packs: how a pull request names
// the issue it closes, and how a span between two timestamps becomes hours.
//
// Published because the usage fold files a merged PR's lead times under the issue its
// body closes, and a page drawing the same series for the days the fold has not
// reached yet has to find that issue by the same rule — otherwise the two halves of
// one series disagree about which PRs have a lead time at all.
//
// Re-exported from the pure module rather than from the reader beside it: the consumer
// is a page that runs in a browser, where the reader's `process.env` and its listing
// would not load.
export { closesIssueIn, hoursBetween } from '../src/items/pr-fields.mjs';
== shared-code/signals.mjs
// The signal shapes a task's precondition is handed, published for other packs: the
// collector's own definitions, so a pack asserting what its task will see asserts
// against what the executor actually produces.
export * from '../src/signals/index.mjs';
export { localSignalContext } from '../src/world/git.mjs';
== shared-code/task-contract.mjs
// Task-declaration validation, published for other packs: the contract a
// `tasks/<name>/task.json` is held to, so a pack's own tests can exercise its task
// declarations against the same rules the scheduler applies.
export * from '../src/contract/task-contract.mjs';

// Running a declaration's precondition the way the executor does, so a pack's tests
// can assert its own tasks' decisions against the real evaluator.
export { evaluatePrecondition } from '../src/execute/loop.mjs';
== shared-code/task-declaration.mjs
// The task declaration as text, published for other packs: the file names a task
// folder may carry, the path matcher a file listing is selected by, the reader that
// lifts fields out of either form, and the agentic defaults the loader fills — all
// without a Node built-in, so a browser bundle can load it.
export * from '../src/contract/task-declaration-text.mjs';
export * from '../src/contract/task-defaults.mjs';
== shared-code/usage-format.mjs
// The usage aggregate's codec, published for other packs: the row fields, the file
// version, and the encode/decode pair. A fleet-wide aggregator copies members' rows
// through, so it reads them back with the same codec the member wrote them with.
export * from '../src/items/usage-format.mjs';
export { USAGE_PATH } from '../tasks/usage-fold/worker.mjs';

== shared-code/wake.mjs
// Which of a repo's declared tasks a scheduler run would instantiate an item for at a
// given instant — the plan a forced sweep has to predict. Its own module rather than a
// line in work-items.mjs: the scheduler run reaches Node built-ins, and the dashboard
// loads work-items.mjs unbundled in a browser, where only relative specifiers resolve.
export { planWake } from '../src/schedule/run.mjs';
== shared-code/work-items.mjs
// The work-item vocabulary, published for other packs: the title grammar that IS a
