import pathlib

BANNER = """// WORKFLOW AND ROUTINE ABI — an entry point, never logic.
//
// Every module in this folder is named as a literal path by a file this repository
// cannot push to: a member's `.github/workflows/`, which lands only as a pull
// request somebody merges, or a routine's stored prompt, which is a per-repo
// console setting. A member therefore spends every window between its mount
// refreshing (nightly) and its workflows being re-merged (whenever) running the
// new code from the old path — so these paths are frozen, and a run that finds
// nothing here is a repo whose queue stops silently with no run left to fix it.
//
// They are the ABI, not a compatibility tolerance: nothing retires them, and
// nothing may put behaviour behind one. The mechanism lives under `src/`.
"""

RUNNABLE = """
import {{ pathToFileURL }} from 'node:url';
import {{ {entry} }} from '{module}';

{extra}export * from '{module}';

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {{
  {entry}().catch((e) => {{ console.error(e.message ?? e); process.exit(1); }});
}}
"""

shims = {
  'queue/scheduler-run.mjs': ('The scheduler run: the tick that asks every declared task whether its window\n// has opened, and files the work items for those that say yes.',
                              'runSchedulerRun', '../src/schedule/run.mjs', ''),
  'queue/drain-dispatch.mjs': ('The post-scheduler-run drain: dispatches the executor workflow so whatever this\n// tick made pickable starts draining now rather than at the next tick.',
                               'runDrainDispatch', '../src/schedule/drain-dispatch.mjs', ''),
  'queue/executor.mjs': ('The executor: the pull worker that claims a ready item, runs it, and converges\n// it or hands it to an agent session.',
                         'runExecutorJob', '../src/execute/loop.mjs', ''),
  'queue/executor-continuation.mjs': ('The continuation of a dead executor run: dispatches a fresh executor so the\n// queue drains rather than waiting for the next tick, and escalates when a chain\n// keeps dying.',
                                      'runExecutorContinuation', '../src/recover/continuation.mjs', ''),
  'queue/workflow-failure.mjs': ('The scheduler workflow\\'s `report-failure` job: a run that went red as a whole\n// reaches a person as one open issue rather than an unwatched red tab.',
                                 'runWorkflowFailureReport', '../src/recover/workflow-failure.mjs', ''),
}

for path, (what, entry, module, extra) in shims.items():
    body = BANNER + '//\n// ' + what + '\n' + RUNNABLE.format(entry=entry, module=module, extra=extra)
    pathlib.Path(path).write_text(body)

# tick.mjs keeps its own word first: the old name for the scheduler run.
pathlib.Path('queue/tick.mjs').write_text(BANNER + """//
// `tick.mjs` is the scheduler run's pre-#877 name. A member whose scheduler
// workflow still says `tick.mjs` is behind the mount and should be re-converged —
// which this says in its own log, since nothing else would notice.

import { runSchedulerRun } from '../src/schedule/run.mjs';

console.log('- invoked as `tick.mjs`, which is the old name for the scheduler run —'
  + ' this repo\\'s scheduler workflow is behind the mount and should be re-converged');
runSchedulerRun().catch((e) => { console.error(e); process.exit(1); });
""")
print('wrote', len(shims) + 1, 'shims')
