1	// THE ESCALATION SURFACE FOR A WORKFLOW THAT FAILED AS A WHOLE (docs/PRINCIPLES.md).
2	// A scheduled run reaches no one when it goes red — nothing is
3	// watching the Actions tab — so a run-level failure becomes a human-visible
4	// issue instead.
5	//
6	// ONE OPEN ISSUE, by a fixed title: create-or-comment, so a week of nightly
7	// failures is one thread rather than seven issues. The labels are ensured
8	// FIRST, because a first-run failure may precede any other label-ensure and
9	// GitHub 422s the write that applies an unknown label.
10	//
11	// The platform reporting its own failure IS an origin (`task:origin:github`),
12	// parked in the `failure` lane — the one a person diagnoses (#1119).
13	//
14	// This lives in the engine rather than in the workflows that call it because
15	// `.github/workflows/` is the one path a converge cannot push into: a member's
16	// copy of a workflow moves only through a PR a human merges, while this module
17	// converges nightly like the rest of the engine.
18	
19	import { pathToFileURL } from 'node:url';
20	import { makeGh } from '../world/github.mjs';
21	import { actionRepoContext, runUrl } from '../world/actions.mjs';
22	import { ensureLabels, createIssue, comment } from '../world/github.mjs';
23	import { ORIGIN_GITHUB, STATUS_NEEDS_HUMAN_FAILURE } from '../items/work-item.mjs';
24	
25	// Not a queue label: this one marks the issue as the platform's own failure
26	// report rather than a work item, so it is defined here beside its only writer.
27	export const WORKFLOW_FAILURE = 'workflow-failure';
28	
29	export const FAILURE_LABELS = Object.freeze([
30	  { name: WORKFLOW_FAILURE, color: 'b60205', description: 'Claudinite scheduler: a scheduler run or task failed' },
31	  { name: ORIGIN_GITHUB, color: 'd4c5f9', description: 'Claudinite queue: filed by the platform itself — a workflow reporting its own failure' },
32	  { name: STATUS_NEEDS_HUMAN_FAILURE, color: 'b60205', description: 'Claudinite queue: parked — the run broke, diagnose and fix' },
33	]);
34	
35	// The open issue carrying exactly `title`, or null. Lowest number wins, so a past
36	// race that left two converges on the first and the duplicate stays inert.
37	//
38	// A search that does not answer returns null rather than throwing: filing a
39	// second issue is untidy, losing the failure report entirely is not.
40	export async function findOpenFailureIssue(gh, repo, title) {
41	  const want = title.trim();
42	  const q = encodeURIComponent(`repo:${repo} is:issue is:open in:title "${want}"`);
43	  const { status, json } = await gh(`/search/issues?q=${q}&per_page=100`);
44	  if (status !== 200 || !Array.isArray(json?.items)) return null;
45	  const exact = json.items
46	    .filter((i) => (i.title ?? '').trim() === want)
47	    .sort((a, b) => a.number - b.number);
48	  return exact.length ? exact[0].number : null;
49	}
50	
51	export async function reportWorkflowFailure(gh, repo, { title, body }) {
52	  await ensureLabels(gh, repo, FAILURE_LABELS);
53	  const open = await findOpenFailureIssue(gh, repo, title);
54	  if (open != null) {
55	    await comment(gh, repo, open, body);
56	    return { issue: open, created: false };
57	  }
58	  const { number } = await createIssue(gh, repo, {
59	    title, body, labels: FAILURE_LABELS.map((l) => l.name),
60	  });
61	  return { issue: number, created: true };
62	}
63	
64	// The URL of the run doing the reporting, republished here because the failure
65	// report is where every caller of it wants it.
66	export { runUrl };
67	
68	export const SCHEDULER_FAILURE_TITLE = 'Claudinite scheduler run failed';
69	
70	// The scheduler workflow's `report-failure` job. It runs only when the scheduler
71	// run or its drain went red, so it files unconditionally.
72	export async function runWorkflowFailureReport() {
73	  const { repo } = actionRepoContext();
74	  if (!repo) throw new Error('GITHUB_REPOSITORY is not set');
75	  const gh = makeGh();
76	  const { issue, created } = await reportWorkflowFailure(gh, repo, {
77	    title: SCHEDULER_FAILURE_TITLE,
78	    body: `The Claudinite scheduler run/drain run failed: ${runUrl()}`,
79	  });
80	  console.log(`- ${created ? 'filed' : 'commented on'} #${issue}`);
81	}
82	
83	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
84	  runWorkflowFailureReport().catch((e) => { console.error(e); process.exit(1); });
85	}

